CREATE FUNCTION pg_temp.chk(label text, q text, exp text) RETURNS text LANGUAGE plpgsql AS $f$
DECLARE got text[]; want text[]; miss text[]; extra text[];
BEGIN
  EXECUTE 'SET LOCAL ROLE authenticated';
  EXECUTE 'select coalesce(array_agg(x order by x),''{}'') from ('||q||') s(x)' INTO got;
  EXECUTE 'RESET ROLE';
  EXECUTE 'select coalesce(array_agg(x order by x),''{}'') from ('||exp||') s(x)' INTO want;
  SELECT array_agg(x) INTO miss FROM unnest(want) x WHERE x <> ALL(got);
  SELECT array_agg(x) INTO extra FROM unnest(got) x WHERE x <> ALL(want);
  RETURN label||': got='||cardinality(got)||' want='||cardinality(want)||' missing='||coalesce(miss::text,'-')||' extra='||coalesce(extra::text,'-');
END $f$;

