CREATE FUNCTION pg_temp.timeit() RETURNS numeric LANGUAGE plpgsql AS $f$
DECLARE t0 timestamptz; a numeric[] := '{}'; n int; i int;
BEGIN
  FOR i IN 1..41 LOOP
    t0 := clock_timestamp();
    EXECUTE 'select count(*) from public."Content" where id = 60001' INTO n;
    IF n <> 1 THEN RAISE EXCEPTION 'row not visible'; END IF;
    a := a || extract(epoch from clock_timestamp()-t0)*1000;
  END LOOP;
  RETURN round((SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY x) FROM unnest(a) x)::numeric, 3);
END $f$;
GRANT EXECUTE ON FUNCTION pg_temp.timeit() TO authenticated;
GRANT USAGE ON SCHEMA pg_temp TO authenticated;
CREATE FUNCTION pg_temp.setg(n int) RETURNS void LANGUAGE sql AS $f$
  DELETE FROM public."ResourceAccess";
